const b = $input.first().json.body || $input.first().json;
const query = (b.query || b.ticker || '').toString();
const ticker = (b.ticker || '').toString();
const prediction = b.prediction || null;
return [{ json: { query, ticker, prediction } }];

const prev = $('Normalize').first().json;
const incoming = $input.first().json;
let ticker = prev.ticker || incoming.ticker || '';
ticker = (ticker || '').toUpperCase().trim();
if (!ticker) throw new Error('Could not resolve a ticker from: ' + (prev.query || ''));
return [{ json: { ...prev, ticker } }];

const parsed = $('Parse ticker').first().json;
const api = $input.first().json;
const prediction = parsed.prediction || api.prediction || null;
if (!prediction) throw new Error(api.error || 'Prediction failed');
return [{ json: { query: parsed.query, ticker: parsed.ticker, prediction } }];

const merged = $('Merge quote').first().json;
const p = merged.prediction || {};
const company = p.company_name || p.company || merged.ticker;
const brief = `${company} (${merged.ticker}) last closed at ${p.last_close} as of ${p.as_of}. The model estimates ${p.price || p.predicted_close} (${p.mean_return || p.expected_return}), ${p.sentiment || 'unspecified'} news tone, RSI ${p.rsi}, trend ${p.ma_trend || p.trend}. This is a model estimate, not investment advice.`;
return [{ json: { ok: true, ticker: merged.ticker, brief, prediction: merged.prediction } }];
